def transform(grid):
    from collections import Counter
    h, w = len(grid), len(grid[0])
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    fg = next(v for row in grid for v in row if v != bg)
    out = [row[:] for row in grid]
    row_marks = [[c for c in range(w) if grid[r][c] == fg] for r in range(h)]
    col_marks = [[r for r in range(h) if grid[r][c] == fg] for c in range(w)]

    # Bridge across separated foreground marks on rows with 3+ marks.
    for r, cs in enumerate(row_marks):
        if len(cs) >= 3:
            for c in range(cs[0], cs[-1] + 1):
                if out[r][c] == bg:
                    out[r][c] = 2
        elif len(cs) == 2 and any(len(col_marks[c]) == 1 for c in cs):
            for c in range(cs[0], cs[-1] + 1):
                if out[r][c] == bg:
                    out[r][c] = 2

    # Bridge verticals with repeated marks if at least one endpoint is an
    # isolated mark in its row (not merely part of a horizontal stroke).
    for c, rs in enumerate(col_marks):
        if len(rs) >= 3 and any(len(row_marks[r]) == 1 for r in rs):
            for r in range(rs[0], rs[-1] + 1):
                if out[r][c] == bg:
                    out[r][c] = 2
    return out

