    col_marks = [[r for r in range(h) if grid[r][c] == fg] for c in range(w)]
    # Horizontal crossbars with at least three marks: fill the gaps between ends.
    for r, cols in enumerate(row_marks):
        if len(cols) >= 3:
            for c in range(cols[0], cols[-1] + 1):
                if grid[r][c] == bg:
                    out[r][c] = 2
    # Repeated vertical tracks are bridged only if they contain a single-mark row.
    for c, rows in enumerate(col_marks):
        if len(rows) >= 3 and any(len(row_marks[r]) == 1 for r in rows):
            for r in range(rows[0], rows[-1] + 1):
                if grid[r][c] == bg:
                    out[r][c] = 2
    return out

